	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeWhitespace53__c/fields/MailingStreet2__c.field-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>MailingStreet2__c</fullName>\n    <externalId>false</externalId>\n    <label>Mailing Street2</label>\n    <required>false</required>\n    <trackFeedHistory>false</trackFeedHistory>\n    <trackTrending>false</trackTrending>\n    <type>TextArea</type>\n</CustomField>\n")
